vec4 textureLod4(sampler2D s, vec4 uv4) { return textureLod(s, uv4.xy, uv4.w); }
// Custom sampler stubs (mapped to noise texture)
#define sampler_rand00 sampler_noise_lq
#define sampler_pw_noise_lq sampler_noise_lq
#define sat clamp01
sampler sampler_rand00;
sampler sampler_pw_noise_lq;
const float pos_z = q23, kipp = q20, kolb_base = q28, kolb_ampl=q27, Freq = q26;
const float fak = 0.99 * (1.0 - Freq*0.15*30/uFps), trel=q25;
float  glas_mask, glas_form;
float  kolb_rad, kolb_mask0, kolb_mask, kolb_mask2, tmp0, tmp, rx;
vec2 rsk, glas_uv, glas_dz,Glas, kolb_uv, Kolb;
mat2 dis;
static vec4 kolb_mov   = vec4(_qa);
static vec4 kolb_speed = vec4(_qb);
vec3 neu, rsl,ret1,  screen3, sun;
vec2 dz;
static vec3 t = vec3(q14,q15,q16);
static vec3 s = vec3(q17,q18,q19);
static vec3 ts = -cross(s,t);
static vec3 pos = vec3 (q11,q12,q13);
vec3 project () {float z; z = 1.0 / multiply(cross(ts,-t),screen3);
return vec3(multiply(float2x3(ts,t),cross(pos,screen3))*z+0.5,-z);}
float CorrZ   (float rsy) {return kipp*(0.7-rsy*0.6);}

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  screen3 = vec3 ((uv-0.5), 1.0 );
rsl = project ();
vec2 noise = texture(sampler_pw_noise_lq,rsl.xy+rand_frame);
//GLASROHRE
rx = max(min(rsl.x*4.5-2, 2.0 ),-2) + 2.0;
rsk = vec2(fract(rx)-0.5,(rsl.y-0.88) * 3.0)*2.3 ;
glas_form = sqrt(1-1*pow(rsk.x, 2.0 ));
glas_uv =   vec2(-rsk.x/glas_form, 0.0 );;
glas_mask = clamp01(16-16*abs(rsk.x));
Glas = glas_mask*glas_uv;
int kolb_no = int(rx) % 4;
tmp0= kolb_mov[kolb_no];
tmp = (tmp0 + kolb_base)*kolb_ampl;
glas_mask *= (rsl.y > tmp +glas_form*CorrZ(rsl.y));
vec2 uv2 = uv_orig;
dis[0] = (vec2(1.0)/uTexSize) * vec2( 16.0 , 0.0 );
dis[1] = (vec2(1.0)/uTexSize) * vec2( 0.0 ,30.0 * Freq);
dz.x = 2.0 * GetBlur1 (uv2.xy-dis[0]).r - 2.0*GetBlur1 (uv2.xy+dis[0]).r;
dz.y = 2.0 * GetBlur1 (uv2.xy-dis[1]).r - 2.0*GetBlur1 (uv2.xy+dis[1]).r;
//unipolar ueberarbeiten##
dz.y += sat(kolb_speed[kolb_no]) * -16.0/uFps *  sat(1-4*(rsl.y-tmp));
//dz += glas_uv*0.041; //interessant #
ret.r = (audioLow+audioMid)*exp(-3*max(abs(rsk.x),abs(rsk.y))) *q24 * (kolb_no==q10) ; //nicht mit frequ multiplizieren
//Zuendung klappt nur wenn rsk = 0 noch auf dem Bild
ret.r = max(ret.r, GetPixel(uv + dz*-0.12).r*fak - 0.002*(noise-0.5))* glas_mask  ;//Rechenzeit#
vec2 uv3 = fract(rsl + vec2( 0.0 ,-q29 * 8.0))-0.5;
uv3 = pow(uv3-vec2(0.4, 0.0 ), 2.0 ) * 300.0;
ret.g = sat(1.0 - uv3.y);
ret.g = max(ret.g,sat(1.0 - uv3.x -0.2*(uv3.y>8)));
float test = texture(sampler_pw_noise_lq,rsl*0.05) * (1.0 - rsl.y);
ret.g += (ret.g==0)*test;
  fragColor = vec4(ret, 1.0);
}

