  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  screen3 = vec3 ((uv-0.5), 1.0 );
rsl = project();
rx = max(min(rsl.x*4.5-2, 2.0 ),-2) + 2.0;
vec2 ypos = vec2 (0.2, (kolb_mov[rx%4] + kolb_base)*kolb_ampl);
vec2 xpos = (fract(rx)-0.5) *vec2 (2.1,2.4);
vec2 xarg = pow(xpos, 2.0 );
vec2 form = sqrt(1.0 - xarg);
//FORM GLAS
glas_uv = vec2 (-xpos[0]/form[0], 1.2-form[0]);
glas_form = form[0];
glas_mask =  sat(16-16*xarg[0])* (rsl.y >(ypos[0] +form[0]*CorrZ(rsl.y)));
Glas = glas_mask*glas_uv;
//FORM KOLBEN
float rely = ypos[1]+form[1]*CorrZ(rsl.y)-rsl.y;
xpos[1] *= 1.0 + sat(100.0 * rely - 30.0);
xarg[1] = pow(xpos[1], 2.0 );
float ymod = (floor(20.0 * rely))%2 * (rely < 0.3);
kolb_uv = vec2 (-xpos[1]/form[1], ymod-form[1]+1.4); //###
kolb_form = form[1];
tmp = form[1]*CorrZ(rsl.y);
kolb_mask = sat(16-16*xarg[1]*(1+0*ymod)) * ((ypos[1]-tmp)>rsl.y);
kolb_mask2 = (kolb_mask) *  (rsl.y > ypos[1]+tmp);
Kolb = kolb_mask*kolb_uv;
//KOORDINATEN
uv_fire=uv;
uv_back= uv + vec2 (Glas.x*-0.05, 0.0 );
uv_spiegelf = uv_back; //gleich halten
uv_refl = uv - vec2 (.1,1.2) * 0.0;
//HINTERGRUND
vec2 rr = (vec2(1.0)/uTexSize) * 2.0;
dz.x = GetPixel (uv_back-rr).g - GetPixel (uv_back+rr).g - 0.06;
dz.y = 0;
back = GetPixel(uv_back).g  ;
float prof = max(max(back * 0.0,glas_form),kolb_form * 0.0);
float test = fract(q30+(rsl.x - 0.0*rsl.y+prof * 0.0)*0.2)<0.2;
sun = (0.5/length(uv_back+dz * 18.0 +vec2(1.2, 0.0 ))) * ( 1.0 - uv.y);
back =  sun * back * vec3 ( 1.0 ,0.7,0.5);
back *= 1.0 - kolb_mask;
ret1 = back;
//FEUER
ret1 *= sat(1-8*GetPixel(uv).r);
ret1 += lavcol(GetPixel(uv_fire).r) ;
//REFLEKTION KOLBEN
float refk = sat(.06/pow(length(0.2+uv_refl-Kolb), 1.0 )) * kolb_mask * (kolb_mask2 == 0.0 ? 1.0 : 0.0);
ret1 += refk* (test == 0.0 ? 1.0 : 0.0);
ret1 += (vec3(glow,glow / 8.0, 0.0 )* (1-3*rely) * (1.0 + kolb_mask2 / 2.0*0)) *kolb_mask;
//TRANSMISSION GLAS
float gg = glas_mask/glas_form;
ret1 = ret1-.05*gg;
ret1 += .16*vec3( 0.0 , 1.0 , 1.0 ) * (1.0 - rsl.y)*gg * (test == 0.0 ? 1.0 : 0.0);
//REFLEKTTION GLAS
float refg = (.04/length((uv_refl-Glas * 2.0+0))) * gg;
ret1 += refg*(test == 0.0 ? 1.0 : 0.0);
ret1 += GetPixel(uv_spiegelf).r*vec3( 2.0 ,0.8,0.5) * (glas_form > 0.1);
ret = ret1;
//ret = GetPixel(uv).g;
  fragColor = vec4(ret, 1.0);
}

